 const [notices,setNotices]=useState(false),[query,setQuery]=useState(''),[status,setStatus]=useState(''),[hospitalId,setHospitalId]=useState(''),[leaderId,setLeaderId]=useState(''),[range,setRange]=useState<string[]>(()=>periodRange('3m'));
 const [department,setDepartment]=useState('');
