 useEffect(()=>{const previous=previousTableFilter.current;if(previous.route===route&&previous.signature!==tableFilterSignature)window.dispatchEvent(new Event('clinivol-admin-reset-pages'));previousTableFilter.current={route,signature:tableFilterSignature}},[route,tableFilterSignature]);
 const [inspect,setInspect]=useState<Doctor|Approval|Person|Asset|AuditEvent|Task|null>(null),[inspectKind,setInspectKind]=useState('');
 const [command,setCommand]=useState<Command|null>(null),[reason,setReason]=useState(''),[basis,setBasis]=useState(''),[selection,setSelection]=useState(''),[date,setDate]=useState(''),[commandError,setCommandError]=useState(''),[commandConflict,setCommandConflict]=useState(false),[busy,setBusy]=useState(false),[preview,setPreview]=useState('');
 const [hospitalEdit,setHospitalEdit]=useState<Hospital|null|undefined>(undefined),[departmentEdit,setDepartmentEdit]=useState<{hospital:Hospital;initial?:Department}|null>(null);
 const [orderFile,setOrderFile]=useState<{orderId:string;file:Attachment}|null>(null);
 const [preferences,setPreferences]=useState({taskAssigned:true,reviewResult:true,doctorComments:true,systemMessages:true});
 const refresh=useCallback(async()=>{try{setData(await adminRequest<AdminState>());setError('')}catch(e){setError((e as Error).message)}finally{setLoading(false)}},[]);
 useEffect(()=>{void refresh()},[refresh]);
 useEffect(()=>{const update=()=>{const value=location.hash.replace(/^#(?:admin\/?)?/,'');setRoute(value.startsWith('auth/')?'home':value==='home'?'home':value||'home')};window.addEventListener('hashchange',update);window.addEventListener('popstate',update);return()=>{window.removeEventListener('hashchange',update);window.removeEventListener('popstate',update)}},[]);
 useEffect(()=>{storage.setItem('admin-collapsed',collapsed?'1':'0')},[collapsed,storage]);
 const returnContext=useRef<{route:string;query:string;status:string;hospitalId:string;leaderId:string;department:string;range:string[];tab:string;stage:string;assignee:string;scroll:number}[]>([]);
 const moduleContexts=useRef<Record<string,{query:string;status:string;hospitalId:string;leaderId:string;department:string;range:string[];stage:string;assignee:string}>>({});
 const go=(value:string,remember=true,reset=false)=>{if(remember&&!route.includes('/'))moduleContexts.current[route]={query,status,hospitalId,leaderId,department,range,stage:stageFilter,assignee:assigneeFilter};if(remember&&(value.startsWith('order/')||value.startsWith('hospital/')))returnContext.current.push({route,query,status,hospitalId,leaderId,department,range,tab,stage:stageFilter,assignee:assigneeFilter,scroll:document.querySelector('.platform-main')?.scrollTop||0});else if(remember)returnContext.current=[];setQuery('');setStatus('');setHospitalId('');setLeaderId('');setDepartment('');setRange(value==='orders'||value==='orders/risk'?periodRange('3m'):[]);setStageFilter('');setAssigneeFilter('');const saved=!reset?moduleContexts.current[value]:undefined;if(saved){setQuery(saved.query);setStatus(saved.status);setHospitalId(saved.hospitalId);setLeaderId(saved.leaderId);setDepartment(saved.department);setRange(saved.range);setStageFilter(saved.stage);setAssigneeFilter(saved.assignee)}location.hash=`admin/${value}`;setRoute(value)};
 const goBack=(fallback:string)=>{const previous=returnContext.current.pop();if(!previous){go(fallback);return}go(previous.route,false);setQuery(previous.query);setStatus(previous.status);setHospitalId(previous.hospitalId);setLeaderId(previous.leaderId);setDepartment(previous.department);setRange(previous.range);setStageFilter(previous.stage);setAssigneeFilter(previous.assignee);setModuleTab(previous.route.split('/')[0],previous.tab);requestAnimationFrame(()=>{const main=document.querySelector('.platform-main');if(main)main.scrollTop=previous.scroll})};
 const backLabel=(fallback:string)=>'返回'+(menu.find(([key])=>key===returnContext.current.at(-1)?.route.split('/')[0])?.[1]||fallback);
 const theme=(value:'light'|'dark'|'system')=>{const next=value==='dark'||value==='system'&&matchMedia('(prefers-color-scheme:dark)').matches;setDark(next);document.documentElement.setAttribute('theme-mode',next?'dark':'light');document.documentElement.dataset.theme=next?'dark':'light';localStorage.setItem('clinivol-theme-preference',value)};
 const start=(value:Command)=>{setCommand(value);setReason('');setBasis(value.basis||'');setSelection(value.options?.length===1?value.options[0].value:'');setDate(value.date||'');setCommandError('');setCommandConflict(false)};
 const commandFlight=useRef(false);
 const commit=async()=>{if(!command||busy||commandFlight.current)return;const invalid=command.options&&!selection?'请选择'+(command.selectLabel||'操作对象')+'。':(['assign-task'].includes(command.action)||command.action==='review-order'&&command.result==='approved')&&!/^\d{4}-\d{2}-\d{2}$/.test(date)?'请选择有效日期。':(command.action==='revoke-permission'||command.result==='approved'&&['review-doctor','review-account','approve-permission'].includes(command.action)||command.action==='request-permission')&&!basis.trim()?'请填写书面审批依据。':command.result!=='approved'&&!reason.trim()?'请填写'+(command.result==='returned'?'退回原因':'操作原因')+'。':'';if(invalid){setCommandError(invalid);return}commandFlight.current=true;setBusy(true);setCommandError('');try{const result=await adminRequest<{ok:boolean;data?:unknown}>('command',{action:command.action,id:command.id,version:command.version,result:command.result,reason,basis,leaderId:selection,assignee:selection,reviewerId:selection,permission:selection,plannedDate:date,confirmedDeliveryDate:date});if(result.data){const url=URL.createObjectURL(new Blob([JSON.stringify(result.data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='admin-isolated-asset-metadata.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}await refresh();await auth.refresh();setCommand(null);if(!['review-doctor','review-account','approve-permission'].includes(command.action))setInspect(null);void MessagePlugin.success('操作已完成')}catch(e){setCommandError((e as Error).message);if((e as Error & {status?:number}).status===409){setCommandConflict(true);await refresh()}}finally{commandFlight.current=false;setBusy(false)}};
 useEffect(()=>{setInspect(null);setCommand(null);setPreview('')},[route]);
 useEffect(()=>{if(route.startsWith('reviews/doctor/')&&data){const d=data.doctors.find(d=>d.id===route.split('/')[2]);if(d){setInspectKind('doctor');setInspect(d)}}},[route,data]);
 const user={...account,role:roleName(account)};
 const section=route.split('/')[0],detail=route.split('/')[1],settings=['profile','security','preferences'].includes(section),active=section==='order'?'orders':section==='hospital'?'organizations':section;
 const buckets=useMemo(()=>data?dashboardBuckets(data,new Date(),account.permissions):null,[data,account.permissions]);
