 const businessNo=(id:string)=>{const o=data?.orders.find(o=>o.id===id);return o?.status==='草稿'?'-':o?.businessNo||'—'};
 const orderLink=(id:string)=><Button className="admin-business-number" variant="text" theme="default" disabled={!data?.orders.some(o=>o.id===id)} onClick={()=>go(`order/${id}`)}>{businessNo(id)}</Button>;
 const can=(permission:string)=>account.permissions.includes(permission);
 const canReview=['doctors:review','accounts:approve','permissions:grant'].some(can);
 const doctorReviewMode=inspectKind==='doctor'&&(section==='reviews'||section==='home');
 const visibleMenu=menu.filter(([value])=>value!=='tasks'&&(value==='home'||value==='reviews'&&canReview||can(({orders:'orders:read',tasks:'tasks:assign',reviews:'doctors:review',organizations:'people:manage',permissions:'permissions:grant',assets:'assets:read',audit:'audit:read'} as Record<string,string>)[value])));
 const navGroup=(value?:string)=>['orders','tasks','reviews'].includes(value||'')?'业务工作':['organizations','permissions'].includes(value||'')?'组织与权限':['assets','audit'].includes(value||'')?'数据与审计':'';
 const chronological=<T extends {id:string}>(rows:T[],at:(r:T)=>string)=>[...rows].sort((a,b)=>(Date.parse(at(b))||0)-(Date.parse(at(a))||0)||a.id.localeCompare(b.id));
 const hospital=(id:string)=>data?.hospitals.find(h=>h.id===id)?.name||'—';
 const doctor=(id:string)=>data?.doctors.find(d=>d.id===id)?.name||'—';
 const auditObject=(event:AuditEvent)=>{const id=event.objectId,task=data?.tasks.find(t=>t.id===id),asset=data?.assets.find(a=>a.id===id);if(data?.orders.some(o=>o.id===id))return businessNo(id);if(task||asset)return businessNo((task||asset)!.orderId);return data?.doctors.find(d=>d.id===id)?.name||data?.people.find(p=>p.id===id)?.name||data?.hospitals.find(h=>h.id===id)?.name||data?.approvals.find(a=>a.id===id)?.subjectName||data?.materials.find(m=>m.id===id)?.name||'平台操作'};
