  {selectFilter('医院',hospitalId,value=>{setHospitalId(value);if(!data?.hospitals.some(h=>(!value||h.id===value)&&h.departments.includes(department)))setDepartment('')},data?.hospitals.map(h=>({label:h.name,value:h.id}))||[])}
